# 10. cause-effect matrix
cols=['СОУЭ','желдету\nөшіру','түтін\nшығару','лифт\nтүседі','есік\nашу']
rows=[('«Назар»',[0,0,0,0,0],'тек ППКП, кезекші'),('«Өрт», 2-қабат',[1,1,1,1,1],''),('ИКЗ ақауы',[0,0,0,0,0],'«Ақау» хабары')]
def matrix():
    o=''
    for j,cn in enumerate(cols):
        ls=cn.split('\n');o+=''.join(T(130+j*42,14+k*12,l,'t-s') for k,l in enumerate(ls))
    for i,(rn,v,note) in enumerate(rows):
        y=40+i*52;o+=TL(4,y+16,rn,'t-s t-b')
        for j,b in enumerate(v):
            o+=R(114+j*42,y,32,26,'bxa' if b else 'bx')+(T(130+j*42,y+17,'✓','t-s t-b') if b else '')
        if note:o+=TL(114,y+40,note,'t-s mu')
    return o
